  await expect(page.getByText('Forked from acme-docs', { exact: true })).toBeVisible();
  await page.reload();
  await expect(page.getByRole('heading', { name: new RegExp(forkName) })).toBeVisible();
  await expect(page.getByText('Forked from acme-docs', { exact: true })).toBeVisible();

